package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// stripDangerousChars removes characters that could break out of HTML context
func stripDangerousChars(input string) string {
	re := regexp.MustCompile(`[<>{}]`)
	return re.ReplaceAllString(input, "")
}

// normalizeWhitespace collapses multiple spaces (defense-in-depth)
func normalizeWhitespace(input string) string {
	re := regexp.MustCompile(`\s+`)
	return re.ReplaceAllString(strings.TrimSpace(input), " ")
}

type Invoice struct {
	ID        int     `json:"id"`
	Vendor    string  `json:"vendor"`
	Amount    float64 `json:"amount"`
	Status    string  `json:"status"`
	AccountNo string  `json:"account_no"`
}

func searchInvoices(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	vendor := r.URL.Query().Get("vendor")
	status := r.URL.Query().Get("status")

	// Apply sanitization
	vendor = stripDangerousChars(vendor)
	vendor = normalizeWhitespace(vendor)

	// Status must be one of known values
	validStatuses := map[string]bool{"pending": true, "paid": true, "overdue": true, "all": true}
	if !validStatuses[strings.ToLower(status)] {
		status = "all"
	}

	var query string
	if status == "all" {
		query = fmt.Sprintf("SELECT id, vendor, amount, status, account_no FROM invoices WHERE vendor ILIKE '%%%s%%'", vendor)
	} else {
		query = fmt.Sprintf("SELECT id, vendor, amount, status, account_no FROM invoices WHERE vendor ILIKE '%%%s%%' AND status = '%s'", vendor, status)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var invoices []Invoice
	for rows.Next() {
		var inv Invoice
		if err := rows.Scan(&inv.ID, &inv.Vendor, &inv.Amount, &inv.Status, &inv.AccountNo); err != nil {
			continue
		}
		invoices = append(invoices, inv)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(invoices)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/invoices/search", searchInvoices)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
